// In-process llmsim server for Node.js / TypeScript tests.
//
// Decisions:
// - The native addon (`index.cjs`, generated by napi) is CommonJS; this ESM
//   wrapper loads it with createRequire so the package stays `type: module`.
// - Option sources merge in a fixed order, later wins: configFile/toml,
//   config, shortcut options. Same order as the Python package.
// - Defaults bind 127.0.0.1 on port 0 (a free port) so parallel test workers
//   never collide.

import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import type * as NativeModule from "./index.cjs";

const require = createRequire(import.meta.url);
const native = require("./index.cjs") as typeof NativeModule;

/** Config shaped like the `llmsim serve` TOML file. Unknown keys are ignored. */
export interface LlmSimConfig {
  server?: { host?: string; port?: number; max_websocket_connections?: number };
  latency?: {
    profile?: string;
    ttft_mean_ms?: number;
    ttft_stddev_ms?: number;
    tbt_mean_ms?: number;
    tbt_stddev_ms?: number;
  };
  response?: {
    generator?: string;
    target_tokens?: number;
    script_path?: string;
    scenarios_path?: string;
  };
  errors?: {
    rate_limit_rate?: number;
    server_error_rate?: number;
    timeout_rate?: number;
    timeout_after_ms?: number;
  };
  models?: { available?: string[] };
  [section: string]: unknown;
}

export interface ServerOptions {
  /** Object shaped like the TOML config, e.g. `{ errors: { rate_limit_rate: 0.1 } }`. */
  config?: LlmSimConfig;
  /** TOML config text. */
  toml?: string;
  /** Path to a TOML config file. */
  configFile?: string;
  /** Bind address. Default `127.0.0.1`. */
  host?: string;
  /** Bind port. Default `0` (pick a free port). */
  port?: number;
  /** `lorem`, `echo`, `random`, `sequence` or `fixed:<text>`. */
  generator?: string;
  /** Target response length in tokens. */
  targetTokens?: number;
  /** Named latency profile: `instant`, `fast`, `gpt5`, `claude-sonnet`, ... */
  latency?: string;
  /** Path to a scripted-mode YAML/JSON file. */
  script?: string;
  /** Path to a scenarios file or directory. */
  scenarios?: string;
}

/** Counters reported by `GET /llmsim/stats`. */
export interface Stats {
  uptime_secs: number;
  total_requests: number;
  active_requests: number;
  streaming_requests: number;
  non_streaming_requests: number;
  completions_requests: number;
  responses_requests: number;
  websocket_requests: number;
  messages_requests: number;
  image_requests: number;
  systemone_requests: number;
  active_websocket_connections: number;
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
  total_errors: number;
  rate_limit_errors: number;
  server_errors: number;
  timeout_errors: number;
  requests_per_second: number;
  avg_latency_ms: number;
  min_latency_ms: number | null;
  max_latency_ms: number | null;
  model_requests: Record<string, number>;
}

/** Version of the native addon. */
export const version: string = native.nativeVersion();

type Plain = Record<string, unknown>;

function isPlain(value: unknown): value is Plain {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function merge(base: Plain, overrides: Plain): Plain {
  const out: Plain = { ...base };
  for (const [key, value] of Object.entries(overrides)) {
    const current = out[key];
    out[key] = isPlain(value) && isPlain(current) ? merge(current, value) : value;
  }
  return out;
}

function toNative(options: ServerOptions): { toml: string | undefined; overrides: string } {
  if (options.toml !== undefined && options.configFile !== undefined) {
    throw new TypeError("pass either toml or configFile, not both");
  }
  const toml =
    options.configFile !== undefined ? readFileSync(options.configFile, "utf8") : options.toml;

  let overrides: Plain = {
    server: { host: options.host ?? "127.0.0.1", port: options.port ?? 0 },
  };
  if (options.config) overrides = merge(overrides, options.config as Plain);

  const response: Plain = {};
  if (options.generator !== undefined) response.generator = options.generator;
  if (options.targetTokens !== undefined) response.target_tokens = options.targetTokens;
  if (options.script !== undefined) response.script_path = options.script;
  if (options.scenarios !== undefined) response.scenarios_path = options.scenarios;
  if (Object.keys(response).length > 0) overrides = merge(overrides, { response });
  if (options.latency !== undefined) {
    overrides = merge(overrides, { latency: { profile: options.latency } });
  }
  return { toml, overrides: JSON.stringify(overrides) };
}

/** Validate options and return the effective config without starting a server. */
export function resolveConfig(options: ServerOptions = {}): LlmSimConfig {
  const { toml, overrides } = toNative(options);
  return JSON.parse(native.resolveConfigNative(toml, overrides)) as LlmSimConfig;
}

/** An llmsim HTTP server running inside this process. */
export class Server implements AsyncDisposable {
  readonly #native: NativeModule.NativeServer;
  readonly config: LlmSimConfig;

  private constructor(nativeServer: NativeModule.NativeServer, config: LlmSimConfig) {
    this.#native = nativeServer;
    this.config = config;
  }

  /** Bind and start serving. Resolves once the port is bound. */
  static async start(options: ServerOptions = {}): Promise<Server> {
    const { toml, overrides } = toNative(options);
    const config = JSON.parse(native.resolveConfigNative(toml, overrides)) as LlmSimConfig;
    return new Server(await native.startServerNative(toml, overrides), config);
  }

  /** Base URL, e.g. `http://127.0.0.1:41234`. */
  get url(): string {
    return this.#native.url;
  }

  get host(): string {
    return this.#native.host;
  }

  get port(): number {
    return this.#native.port;
  }

  get isRunning(): boolean {
    return this.#native.isRunning;
  }

  /** `baseURL` for the `openai` SDK. */
  get openaiBaseUrl(): string {
    return `${this.url}/openai/v1`;
  }

  /** `baseURL` for `@anthropic-ai/sdk` (the SDK appends `/v1`). */
  get anthropicBaseUrl(): string {
    return `${this.url}/anthropic`;
  }

  /** Base URL for OpenResponses clients. */
  get openresponsesBaseUrl(): string {
    return `${this.url}/openresponses/v1`;
  }

  /** Request, token, and latency counters. Throws once stopped. */
  stats(): Stats {
    return JSON.parse(this.#native.statsJson()) as Stats;
  }

  /** Gracefully stop the server. Idempotent. */
  async stop(): Promise<void> {
    await this.#native.stop();
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await this.stop();
  }
}

/** Shorthand for `Server.start(options)`. */
export function startServer(options: ServerOptions = {}): Promise<Server> {
  return Server.start(options);
}
